package com.example.domain.model.i18n

internal object DuaGu2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("ત્રણ કુલ (મુઅવ્વિઝાત)", "(સૂરહ ઇખ્લાસ) કહો: તે અલ્લાહ એક છે. અલ્લાહ બેનિયાઝ છે. તેણે કોઈને જન્મ આપ્યો નથી અને તે કોઈથી જન્મ્યો નથી. અને તેની બરાબરીનો કોઈ નથી.\n\n(સૂરહ ફલક) કહો: હું સવારના રબની પનાહ માગું છું, તેણે સર્જેલી દરેક વસ્તુની બૂરાઈથી, અંધારી રાતની બૂરાઈથી જ્યારે તે છવાઈ જાય, ગાંઠોમાં ફૂંકનારીઓની બૂરાઈથી, અને ઈર્ષ્યા કરનારની બૂરાઈથી જ્યારે તે ઈર્ષ્યા કરે.\n\n(સૂરહ નાસ) કહો: હું માણસોના રબની પનાહ માગું છું, માણસોના બાદશાહની, માણસોના પૂજ્યની, તે વસવસો નાખનારની બૂરાઈથી જે (અલ્લાહનો ઝિક્ર સાંભળીને) પાછળ હટી જાય છે, જે લોકોના દિલોમાં વસવસો નાખે છે, પછી તે જિન્નોમાંથી હોય કે માણસોમાંથી.", "સવાર-સાંજ ત્રણેય સૂરહ ત્રણ-ત્રણ વખત, અને સૂતાં પહેલાં હાથ પર ફૂંકીને શરીર પર ફેરવવા.", "સવાર-સાંજ ત્રણ વખત પઢવું દરેક વસ્તુથી પૂરતું થઈ જાય છે."),
        "dua_sabr" to DuaText("ધીરજ અને દૃઢતા માટે", "હે અમારા રબ! અમારા પર ધીરજ વરસાવ, અમારા પગ જમાવી દે અને કાફિર કોમ સામે અમારી મદદ કર.", "મુશ્કેલી અને મુકાબલાના સમયે.", "તાલૂતના લશ્કરની દુઆ."),
        "dua_rabbana_innana_amanna" to DuaText("માફી અને આગથી રક્ષણ", "હે અમારા રબ! અમે ઈમાન લાવ્યા, તેથી અમારાં પાપ માફ કર અને અમને આગના અઝાબથી બચાવ.", "કુરઆની દુઆ.", "મુત્તકીઓના ગુણોમાં વર્ણવેલી દુઆ."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("અમારા કામમાં માર્ગદર્શન (અસ્હાબે કહફ)", "હે અમારા રબ! અમને તારી પાસેથી રહમત આપ અને અમારા કામમાં અમારા માટે સાચો માર્ગ સરળ કર.", "ગુફાવાળાઓની દુઆ.", "નિર્ણયો અને મુશ્કેલ સંજોગોમાં માર્ગદર્શન."),
        "dua_musa_faqir" to DuaText("રોજી માટે મૂસા (અ.) ની દુઆ", "હે મારા રબ! તું મારા પર જે પણ ભલાઈ ઉતારે, હું તેનો મોહતાજ છું.", "રોજી અને ભલાઈની માગણી — મદયનમાં મૂસા (અ.) ની દુઆ.", "આ દુઆ પછી અલ્લાહે મૂસા (અ.) ને ઘર, રોજગાર અને પત્ની આપ્યાં."),
        "dua_ayyub" to DuaText("બીમારીમાં અય્યૂબ (અ.) ની દુઆ", "(હે મારા રબ!) મને તકલીફ પહોંચી છે અને તું સૌ દયાળુઓથી વધુ દયાળુ છે.", "બીમારી અને તકલીફમાં.", "અલ્લાહે અય્યૂબ (અ.) ની તકલીફ દૂર કરી દીધી."),
        "dua_husn_khatimah" to DuaText("મુસ્લિમ તરીકે મૃત્યુ (યૂસુફ અ.)", "હે આકાશો અને ધરતીના સર્જનહાર! તું જ દુનિયા અને આખિરતમાં મારો કારસાઝ છે. મને ઇસ્લામની હાલતમાં મૃત્યુ આપ અને નેક લોકો સાથે મેળવી દે.", "સારા અંતની દુઆ.", "યૂસુફ (અ.) ની દુઆ."),
        "dua_shaitan_hamazat" to DuaText("શૈતાનોના વસવસાથી પનાહ", "હે મારા રબ! હું શૈતાનોના વસવસાથી તારી પનાહ માગું છું, અને હે મારા રબ! તેઓ મારી પાસે આવે તેનાથી પણ તારી પનાહ માગું છું.", "શૈતાની વસવસાથી પનાહ.", "કુરઆની પનાહની દુઆ."),
        "dua_bad_character" to DuaText("ખરાબ ચારિત્ર્યથી પનાહ", "હે અલ્લાહ! હું ખરાબ ચારિત્ર્ય, ખરાબ કર્મો અને ખરાબ ઇચ્છાઓથી તારી પનાહ માગું છું.", "ખરાબ ચારિત્ર્ય, કર્મો અને ઇચ્છાઓથી પનાહ.", "નબી ﷺ ની પનાહની દુઆ."),
        "dua_zawal_nimah" to DuaText("કૃપા છીનવાઈ જવાથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું તારી કૃપા છીનવાઈ જવાથી, તેં આપેલી સલામતી બદલાઈ જવાથી, તારા અચાનક અઝાબથી અને તારી દરેક નારાજગીથી.", "કૃપા છીનવાઈ જવા અને અચાનક મુસીબતથી પનાહ.", "નબી ﷺ ની દુઆ."),
        "dua_useless_knowledge" to DuaText("નકામા જ્ઞાનથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું એવા જ્ઞાનથી જે ફાયદો ન આપે, એવા દિલથી જે ન ડરે, એવા મનથી જે ધરાય નહીં, અને એવી દુઆથી જે કબૂલ ન થાય.", "નકામા જ્ઞાન અને નિર્ભય દિલથી પનાહ.", "નબી ﷺ ની પનાહની દુઆ."),
        "dua_beneficial_knowledge" to DuaText("ફાયદાકારક જ્ઞાન અને હલાલ રોજી", "હે અલ્લાહ! હું તારી પાસે ફાયદાકારક જ્ઞાન, પવિત્ર રોજી અને કબૂલ થનાર અમલ માગું છું.", "ફજરની નમાઝ પછી.", "નબી ﷺ ફજરના સલામ પછી આ દુઆ કરતા."),
        "dua_leprosy_diseases" to DuaText("ગંભીર બીમારીઓથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું સફેદ ડાઘ, ગાંડપણ, રક્તપિત્ત અને તમામ ખરાબ બીમારીઓથી.", "ખરાબ બીમારીઓથી રક્ષણ.", "તંદુરસ્તીના રક્ષણની મસનૂન દુઆ."),
        "dua_fear_people" to DuaText("દુશ્મન કે જાલિમનો ડર", "હે અલ્લાહ! અમે તને તેમના મુકાબલે રાખીએ છીએ અને તેમની બૂરાઈથી તારી પનાહ માગીએ છીએ.", "કોઈ કોમ કે વ્યક્તિની બૂરાઈનો ડર હોય ત્યારે.", "નબી ﷺ કોઈ કોમથી જોખમ અનુભવતા ત્યારે આ ફરમાવતા."),
        "dua_shirk_protection" to DuaText("છૂપા શિર્કથી રક્ષણ", "હે અલ્લાહ! હું તારી પનાહ માગું છું જાણીજોઈને તારી સાથે શિર્ક કરવાથી, અને અજાણતાં થાય તેની માફી માગું છું.", "દેખાડો અને છૂપા શિર્કથી બચવા માટે.", "છૂપો શિર્ક કીડીની ચાલથી પણ વધુ છૂપો છે."),
        "dua_rain" to DuaText("વરસાદ પડતી વખતે", "હે અલ્લાહ! ફાયદાકારક વરસાદ વરસાવ.", "વરસાદ પડતી વખતે.", "વરસાદ દુઆ કબૂલ થવાનો સમય છે."),
        "dua_after_rain" to DuaText("વરસાદ પછી", "અલ્લાહની કૃપા અને રહમતથી અમારા પર વરસાદ વરસ્યો.", "વરસાદ પછી.", "આ કહેનાર અલ્લાહ પર ઈમાન રાખનાર છે."),
        "dua_istisqa" to DuaText("વરસાદની પ્રાર્થના (ઇસ્તિસ્કા)", "હે અલ્લાહ! અમારા પર વરસાદ વરસાવ (ત્રણ વખત).", "વરસાદ ન પડે ત્યારે.", "નબી ﷺ એ જુમ્માના ખુત્બામાં આ દુઆ કરી અને વરસાદ પડ્યો."),
        "dua_heavy_rain" to DuaText("વધુ પડતો વરસાદ", "હે અલ્લાહ! અમારી આસપાસ (વરસાવ), અમારા પર નહીં.", "વરસાદ વધુ થઈ જાય ત્યારે.", "નબી ﷺ ની દુઆથી વાદળો હટી ગયાં."),
        "dua_wind" to DuaText("તેજ પવન ફૂંકાય ત્યારે", "હે અલ્લાહ! હું તારી પાસે તેની ભલાઈ, તેમાં જે છે તેની ભલાઈ અને જેની સાથે તે મોકલાયો તેની ભલાઈ માગું છું, અને તેની બૂરાઈ, તેમાં જે છે તેની બૂરાઈ અને જેની સાથે મોકલાયો તેની બૂરાઈથી તારી પનાહ માગું છું.", "તેજ પવન/વાવાઝોડું ફૂંકાય ત્યારે.", "નબી ﷺ વાવાઝોડાના સમયે આ દુઆ કરતા."),
        "dua_thunder" to DuaText("ગર્જના સાંભળીને", "પવિત્ર છે તે જેની પ્રશંસા સાથે ગર્જના તસ્બીહ કરે છે અને ફરિશ્તાઓ પણ તેના ડરથી.", "વાદળોની ગર્જના સાંભળીને — અબ્દુલ્લાહ બિન ઝુબૈર (ર.) નો અમલ.", "સૂરહ રઅદ (૧૩:૧૩) માંથી લીધેલું."),
        "dua_new_moon" to DuaText("નવો ચાંદ જોઈને", "હે અલ્લાહ! આ ચાંદને અમારા પર બરકત, ઈમાન, સલામતી અને ઇસ્લામ સાથે ઉદિત કર. (હે ચાંદ!) મારો અને તારો રબ અલ્લાહ છે.", "નવો ચાંદ જોઈને.", "દરેક નવા મહિનાની મસનૂન દુઆ."),
        "dua_janaza_adult" to DuaText("જનાઝાની નમાઝ (પુખ્ત)", "હે અલ્લાહ! અમારા જીવિતો અને મૃતો, હાજર અને ગેરહાજર, નાના અને મોટા, પુરુષો અને સ્ત્રીઓ બધાને માફ કર. હે અલ્લાહ! અમારામાંથી જેને જીવિત રાખે તેને ઇસ્લામ પર જીવિત રાખ, અને જેને મૃત્યુ આપે તેને ઈમાન પર મૃત્યુ આપ.", "જનાઝાની ત્રીજી તકબીર પછી.", "પુખ્ત મૈયતની મસનૂન દુઆ."),
        "dua_janaza_child" to DuaText("જનાઝાની નમાઝ (બાળક)", "હે અલ્લાહ! તેને અમારા માટે આગળ જનાર (મેજબાન) બનાવ, તેને અમારા માટે સવાબ અને ખજાનો બનાવ, અને તેને અમારા માટે ભલામણ કરનાર અને જેની ભલામણ કબૂલ થાય એવો બનાવ.", "સગીર બાળકના જનાઝામાં (છોકરી હોય તો 'ઇજઅલ્હા').", "હનફીઓમાં પ્રચલિત મસનૂન દુઆ."),
        "dua_mayyit_awf" to DuaText("મૈયત માટે વિગતવાર દુઆ", "હે અલ્લાહ! તેને માફ કર, તેના પર દયા કર, તેને સલામતી આપ, તેને દરગુજર કર, તેની મહેમાની સન્માનજનક કર, તેની કબર વિશાળ કર, તેને પાણી, બરફ અને કરાથી ધોઈ નાખ, અને તેને પાપોથી એવો સાફ કર જેમ સફેદ કપડું મેલથી સાફ કરાય છે.", "જનાઝામાં કે મૈયત માટે.", "ઔફ બિન માલિક (ર.) એ તમન્ના કરી કે કાશ આ મૈયત હું હોત."),
        "dua_visiting_graves" to DuaText("કબ્રસ્તાનની મુલાકાત", "હે મોમિન અને મુસ્લિમ ઘરવાળાઓ, તમારા પર સલામ. અમે પણ ઇન્શાઅલ્લાહ તમને મળનારા છીએ. હું અલ્લાહ પાસે અમારા અને તમારા માટે સલામતી માગું છું.", "કબ્રસ્તાનમાં પ્રવેશતી વખતે.", "કબરોની મુલાકાત મૃત્યુ અને આખિરતની યાદ અપાવે છે."),
        "dua_closing_eyes" to DuaText("મૈયતની આંખો બંધ કરતી વખતે", "હે અલ્લાહ! (ફલાણા) ને માફ કર, હિદાયત પામેલાઓમાં તેનો દરજ્જો ઊંચો કર, તેની પાછળ રહી ગયેલાઓમાં તું તેનો વારસ બની જા, હે સર્વ જગતના રબ! અમને અને તેને માફ કર, તેની કબર વિશાળ કર અને તેમાં પ્રકાશ કરી દે.", "મૈયતની આંખો બંધ કરતી વખતે (નામ લઈને).", "નબી ﷺ એ અબૂ સલમા (ર.) માટે આ દુઆ કરી."),
        "dua_condolence" to DuaText("તાઝિયત (સાંત્વના)", "નિઃશંક અલ્લાહનું જ હતું જે તેણે લઈ લીધું અને તેનું જ છે જે તેણે આપ્યું, અને તેની પાસે દરેક વસ્તુનો નિશ્ચિત સમય છે, તેથી ધીરજ રાખો અને સવાબની આશા રાખો.", "કોઈના અવસાન પર પરિવારને સાંત્વના.", "નબી ﷺ એ પોતાની દીકરીને આ સંદેશો મોકલ્યો."),
        "dua_placing_in_grave" to DuaText("મૈયતને કબરમાં ઉતારવી", "અલ્લાહના નામથી અને રસૂલુલ્લાહ ﷺ ની મિલ્લત પર.", "મૈયતને કબરમાં ઉતારતી વખતે.", "દફનની મસનૂન દુઆ."),
        "dua_sneezing" to DuaText("છીંક આવે ત્યારે", "બધી પ્રશંસા અલ્લાહ માટે. — અલ્લાહ તારા પર દયા કરે. — અલ્લાહ તને હિદાયત આપે અને તારી હાલત સુધારે.", "છીંક આવે ત્યારે; સાંભળનાર 'યરહમુકલ્લાહ' કહે, પછી છીંકનાર જવાબ આપે.", "મુસ્લિમના મુસ્લિમ પરના હકોમાંથી એક."),
        "dua_toilet_enter" to DuaText("શૌચાલયમાં પ્રવેશ", "અલ્લાહના નામથી. હે અલ્લાહ! હું નાપાક નર અને માદા જિન્નોથી તારી પનાહ માગું છું.", "ડાબો પગ મૂકીને શૌચાલયમાં પ્રવેશતાં પહેલાં.", "બિસ્મિલ્લાહ જિન્નો અને માણસના પરદા વચ્ચે આડશ બની જાય છે."),
        "dua_toilet_exit" to DuaText("શૌચાલયમાંથી નીકળતી વખતે", "(હે અલ્લાહ!) હું તારી માફી ચાહું છું.", "જમણો પગ બહાર મૂકીને શૌચાલયમાંથી નીકળતી વખતે.", "નબી ﷺ શૌચાલયમાંથી નીકળીને આ ફરમાવતા."),
        "dua_thanking" to DuaText("કોઈનો આભાર", "અલ્લાહ તને ઉત્તમ બદલો આપે.", "કોઈ ઉપકાર કરે ત્યારે.", "જેણે આ કહ્યું તેણે પ્રશંસાનો હક અદા કર્યો."),
        "dua_love_for_allah" to DuaText("કોઈ કહે 'હું તને અલ્લાહ માટે પ્રેમ કરું છું'", "જેના માટે તું મને પ્રેમ કરે છે તે (અલ્લાહ) તને પ્રેમ કરે.", "કોઈ કહે 'હું તને અલ્લાહ માટે પ્રેમ કરું છું'.", "અલ્લાહ માટે પ્રેમનો મસનૂન જવાબ."),
        "dua_seeing_muslim_smile" to DuaText("સલામ", "તારા પર સલામતી, અલ્લાહની રહમત અને તેની બરકતો હો.", "મુસ્લિમને મળતી વખતે.", "પૂરો સલામ કહેવાથી ત્રીસ નેકીઓ મળે છે."),
        "dua_dressing" to DuaText("કપડાં પહેરવાં", "બધી પ્રશંસા અલ્લાહ માટે જેણે મને આ કપડું પહેરાવ્યું અને મારી કોઈ શક્તિ અને સામર્થ્ય વિના આપ્યું.", "કપડાં પહેરતી વખતે.", "અગાઉનાં પાપોની માફીની ખુશખબર."),
        "dua_rooster_donkey" to DuaText("કૂકડો કે ગધેડાનો અવાજ સાંભળીને", "હે અલ્લાહ! હું તારી કૃપા માગું છું (કૂકડો). — હું ધિક્કારાયેલા શૈતાનથી અલ્લાહની પનાહ માગું છું (ગધેડો).", "કૂકડાના અવાજ પર અલ્લાહની કૃપા માગો, ગધેડાના ભૂંકવા પર શૈતાનથી પનાહ.", "કૂકડો ફરિશ્તો જુએ છે અને ગધેડો શૈતાન."),
        "dua_something_liked" to DuaText("પસંદગીની વસ્તુ જોઈને (નજરથી બચાવ)", "જે અલ્લાહે ચાહ્યું. હે અલ્લાહ! તેમાં બરકત આપ.", "કોઈની સારી વસ્તુ જોઈને બરકતની દુઆ આપો.", "બરકતની દુઆ આપવાથી નજર લાગતી નથી."),
        "dua_sell_buy_debt_repaid" to DuaText("દેવું પાછું આપતી વખતે", "અલ્લાહ તારા પરિવાર અને સંપત્તિમાં બરકત આપે.", "દેવું પાછું આપતી વખતે દેવું આપનાર માટે.", "દેવાનો બદલો આભાર અને ચૂકવણી છે."),
        "dua_talbiyah" to DuaText("તલબિયા", "હું હાજર છું, હે અલ્લાહ હું હાજર છું. હું હાજર છું, તારો કોઈ ભાગીદાર નથી, હું હાજર છું. નિઃશંક બધી પ્રશંસા, કૃપા અને રાજ્ય તારું જ છે, તારો કોઈ ભાગીદાર નથી.", "એહરામ બાંધ્યા પછી ઊંચા અવાજે.", "હજ અને ઉમરાનું પ્રતીક."),
        "dua_yamani_hajar" to DuaText("રુક્ને યમાની અને હજરે અસ્વદ વચ્ચે", "હે અમારા રબ! અમને દુનિયામાં પણ ભલાઈ આપ અને આખિરતમાં પણ ભલાઈ આપ, અને અમને આગના અઝાબથી બચાવ.", "તવાફમાં રુક્ને યમાની અને હજરે અસ્વદ વચ્ચે.", "નબી ﷺ તવાફમાં આ જગ્યાએ આ પઢતા."),
        "dua_safa_marwa" to DuaText("સફા અને મરવા પર", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, રાજ્ય અને પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેણે પોતાનું વચન પૂરું કર્યું, પોતાના બંદાની મદદ કરી અને એકલાએ બધાં લશ્કરોને હરાવ્યાં.", "સફા પર ચઢીને કિબ્લા તરફ મોઢું કરીને (ત્રણ વખત).", "સફા અને મરવા પર નબી ﷺ નો ઝિક્ર."),
        "dua_arafah" to DuaText("અરફાના દિવસની શ્રેષ્ઠ દુઆ", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, રાજ્ય અને પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે.", "અરફાનો દિવસ — શ્રેષ્ઠ દુઆ.", "શ્રેષ્ઠ દુઆ અરફાના દિવસની દુઆ છે, અને શ્રેષ્ઠ વાક્ય આ છે."),
        "dua_takbeer_tashreeq" to DuaText("તકબીરે તશરીક", "અલ્લાહ સૌથી મહાન છે, અલ્લાહ સૌથી મહાન છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી. અલ્લાહ સૌથી મહાન છે, અલ્લાહ સૌથી મહાન છે, અને બધી પ્રશંસા અલ્લાહ માટે જ છે.", "૯ ઝિલ્હજ્જ ફજરથી ૧૩ ઝિલ્હજ્જ અસ્ર સુધી દરેક ફર્ઝ નમાઝ પછી.", "અલી અને ઇબ્ને મસઊદ (ર.) થી વર્ણવાયેલી — હનફીઓમાં વાજિબ."),
        "dua_zamzam" to DuaText("ઝમઝમ પીતી વખતે", "હે અલ્લાહ! હું તારી પાસે ફાયદાકારક જ્ઞાન, વિશાળ રોજી અને દરેક બીમારીથી શિફા માગું છું.", "ઝમઝમ પીતી વખતે જે નિય્યત હોય તેની દુઆ કરો.", "ઝમઝમ જે નિય્યતથી પીવાય તેના માટે જ છે (ઇબ્ને માજા ૩૦૬૨)."),
        "dua_q_ma_khalaqta_batila" to DuaText("સૃષ્ટિ પર ચિંતન", "હે અમારા રબ! તેં આ બધું વ્યર્થ સર્જ્યું નથી, તું પવિત્ર છે, તેથી અમને આગના અઝાબથી બચાવ.", "આકાશો અને ધરતીના સર્જન પર ચિંતન કરનારાઓની દુઆ.", "બુદ્ધિશાળીઓ (ઉલુલ અલ્બાબ) ની દુઆ."),
        "dua_q_sami_na_munadiyan" to DuaText("અમે ઈમાનના પોકારનારને સાંભળ્યો", "હે અમારા રબ! અમે એક પોકારનારને ઈમાન તરફ બોલાવતો સાંભળ્યો કે તમારા રબ પર ઈમાન લાવો, તો અમે ઈમાન લાવ્યા. હે અમારા રબ! અમારાં પાપ માફ કર, અમારી બૂરાઈઓ અમારાથી દૂર કર અને અમને નેક લોકો સાથે મૃત્યુ આપ.", "ઈમાન અને નેક લોકો સાથે મૃત્યુની દુઆ.", "માફી અને સારા અંતની દુઆ."),
        "dua_q_atina_ma_waadtana" to DuaText("જે વચન આપ્યું તે આપ", "હે અમારા રબ! તેં તારા રસૂલો દ્વારા જે વચન આપ્યું તે અમને આપ, અને કયામતના દિવસે અમને રુસવા ન કર, નિઃશંક તું વચનભંગ કરતો નથી.", "કયામતની રુસવાઈથી પનાહ.", "આખિરતમાં ઇજ્જતની માગણી."),
        "dua_q_israfana" to DuaText("અમારી અતિશયોક્તિ માફ કર", "હે અમારા રબ! અમારાં પાપ અને અમારા કામમાં અમારી અતિશયોક્તિ માફ કર, અમારા પગ જમાવી દે અને કાફિર કોમ સામે અમારી મદદ કર.", "અગાઉના નબીઓના સાથીઓની દુઆ.", "દૃઢતા અને માફીની દુઆ."),
        "dua_q_jamiun_nas" to DuaText("તું લોકોને ભેગા કરનાર છે", "હે અમારા રબ! નિઃશંક તું લોકોને એ દિવસે ભેગા કરનાર છે જેમાં કોઈ શંકા નથી. નિઃશંક અલ્લાહ વચનભંગ કરતો નથી.", "કયામત પર વિશ્વાસનો સ્વીકાર.", "જ્ઞાનમાં દૃઢ લોકોની દુઆ."),
        "dua_q_maash_shahidin" to DuaText("અમને ગવાહોમાં લખી લે", "હે અમારા રબ! અમે ઈમાન લાવ્યા, તેથી અમને ગવાહી આપનારાઓ સાથે લખી લે.", "સત્ય ઓળખીને ઈમાન લાવનારાઓની દુઆ.", "ઈમાનની કબૂલિયતની દુઆ."),
        "dua_q_la_tajalna_zalimin" to DuaText("જાલિમો સાથે ન રાખ", "હે અમારા રબ! અમને જાલિમ લોકો સાથે ન રાખ.", "અઅરાફવાળાઓની દુઆ.", "જાલિમોના અંજામથી પનાહ."),
        "dua_q_tawaffana_muslimin" to DuaText("ધીરજ અને મુસ્લિમ તરીકે મૃત્યુ", "હે અમારા રબ! અમારા પર ધીરજ વરસાવ અને અમને મુસ્લિમની હાલતમાં મૃત્યુ આપ.", "ફિરઔનના જાદુગરો ઈમાન લાવ્યા ત્યારની દુઆ.", "આઝમાઇશમાં ધીરજ અને ઈમાન પર અંત."),
        "dua_q_la_tajalna_fitnah" to DuaText("જાલિમો માટે આઝમાઇશ ન બનાવ", "અમે અલ્લાહ પર ભરોસો કર્યો. હે અમારા રબ! અમને જાલિમ કોમ માટે આઝમાઇશ ન બનાવ, અને તારી રહમતથી અમને કાફિર કોમથી છુટકારો આપ.", "મૂસા (અ.) ની કોમની દુઆ.", "જુલ્મ અને જાલિમોથી છુટકારાની દુઆ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("માફી માટે નૂહ (અ.) ની દુઆ", "હે મારા રબ! હું તારી પનાહ માગું છું કે તારી પાસે એવું માગું જેનું મને જ્ઞાન નથી. જો તું મને માફ નહીં કરે અને મારા પર દયા નહીં કરે તો હું નુકસાન ઉઠાવનારાઓમાંથી થઈ જઈશ.", "નૂહ (અ.) ની તૌબાની દુઆ.", "અદબ સાથે દુઆ માગવાનું શિક્ષણ."),
        "dua_q_mudkhala_sidq" to DuaText("સત્ય સાથે પ્રવેશ અને નિર્ગમન", "હે મારા રબ! મને સત્ય સાથે દાખલ કર અને સત્ય સાથે બહાર કાઢ, અને તારી પાસેથી મને મદદગાર શક્તિ આપ.", "કોઈ નવા કામ, ઘર કે જગ્યામાં પ્રવેશતાં પહેલાં.", "હિજરતના પ્રસંગે નબી ﷺ ને શીખવેલી દુઆ."),
        "dua_q_la_tadharni_fardan" to DuaText("મને એકલો ન છોડ (ઝકરિયા અ.)", "હે મારા રબ! મને એકલો ન છોડ, અને તું સૌથી ઉત્તમ વારસ છે.", "સંતાનની માગણી માટે.", "આ દુઆ પર અલ્લાહે યહ્યા (અ.) આપ્યા."),
        "dua_q_munzalan_mubarakan" to DuaText("બરકતવાળી જગ્યાએ ઉતાર", "હે મારા રબ! મને બરકતવાળી જગ્યાએ ઉતાર, અને તું સૌથી ઉત્તમ ઉતારનાર છે.", "નવા ઘરમાં જતી વખતે કે ક્યાંક ઊતરતી વખતે — નૂહ (અ.) ની દુઆ.", "નવી જગ્યામાં બરકતની દુઆ."),
        "dua_q_amanna_faghfir" to DuaText("અમે ઈમાન લાવ્યા, અમને માફ કર", "હે અમારા રબ! અમે ઈમાન લાવ્યા, તેથી અમને માફ કર અને અમારા પર દયા કર, અને તું સૌથી ઉત્તમ દયા કરનાર છે.", "અલ્લાહના નેક બંદાઓની દુઆ.", "માફી અને રહમતની વ્યાપક દુઆ."),
        "dua_q_isrif_jahannam" to DuaText("જહન્નમનો અઝાબ ફેરવી દે", "હે અમારા રબ! જહન્નમનો અઝાબ અમારાથી ફેરવી દે, નિઃશંક તેનો અઝાબ ચોંટી રહેનાર છે. નિઃશંક તે ખરાબ ઠેકાણું અને ખરાબ જગ્યા છે.", "રહમાનના બંદાઓની દુઆ.", "જહન્નમથી પનાહની કુરઆની દુઆ."),
        "dua_q_hab_li_hukman" to DuaText("હિકમત અને જન્નત (ઇબ્રાહીમ અ.)", "હે મારા રબ! મને હિકમત આપ અને નેક લોકો સાથે મેળવી દે, પછીની પેઢીઓમાં મારું સારું સ્મરણ ચાલુ રાખ, અને મને નેમતોવાળી જન્નતના વારસોમાંથી બનાવ.", "હિકમત, નેક લોકોની સોબત અને જન્નતની માગણી.", "ઇબ્રાહીમ (અ.) ની વ્યાપક દુઆ."),
        "dua_q_lut_najjini_ahli" to DuaText("મારા પરિવારને બચાવ (લૂત અ.)", "હે મારા રબ! મને અને મારા પરિવારને તેમનાં કર્મો (ના પરિણામ) થી છુટકારો આપ.", "ખરાબ વાતાવરણથી પરિવારનું રક્ષણ.", "બૂરાઈથી પરિવારનું રક્ષણ."),
        "dua_q_sulaiman_awzini" to DuaText("આભાર માટે સુલૈમાન (અ.) ની દુઆ", "હે મારા રબ! મને તૌફીક આપ કે હું તારી એ કૃપાનો આભાર માનું જે તેં મારા પર અને મારાં માતા-પિતા પર કરી, અને એવો નેક અમલ કરું જે તને પસંદ હોય, અને તારી રહમતથી મને તારા નેક બંદાઓમાં દાખલ કર.", "કૃપા પર આભારની તૌફીક.", "સુલૈમાન (અ.) ની આભારની દુઆ."),
        "dua_q_musa_zalamtu" to DuaText("મેં મારી જાત પર જુલ્મ કર્યો (મૂસા અ.)", "હે મારા રબ! મેં મારી જાત પર જુલ્મ કર્યો, તેથી મને માફ કર.", "ભૂલ થાય ત્યારે તરત તૌબા.", "અલ્લાહે મૂસા (અ.) ને માફ કરી દીધા."),
        "dua_q_musa_najjini" to DuaText("જાલિમોથી બચાવ (મૂસા અ.)", "હે મારા રબ! મને જાલિમ કોમથી છુટકારો આપ.", "જાલિમોના ડરમાં.", "મિસ્રમાંથી નીકળતી વખતે મૂસા (અ.) ની દુઆ."),
        "dua_q_lut_unsurni" to DuaText("ફસાદ કરનારા સામે મદદ (લૂત અ.)", "હે મારા રબ! ફસાદ કરનારી કોમ સામે મારી મદદ કર.", "ફસાદ કરનારાઓ સામે મદદ.", "સત્ય પર દૃઢ રહેનારાઓની દુઆ."),
        "dua_q_hab_li_salihin" to DuaText("નેક સંતાન માટે ઇબ્રાહીમ (અ.) ની દુઆ", "હે મારા રબ! મને નેક (સંતાન) આપ.", "નેક સંતાનની માગણી.", "આ દુઆ પર ઇસ્માઈલ (અ.) મળ્યા."),
        "dua_q_wasita_kulla_shay" to DuaText("અર્શ ઉપાડનાર ફરિશ્તાઓની દુઆ", "હે અમારા રબ! તારી રહમત અને જ્ઞાન દરેક વસ્તુને ઘેરી વળેલાં છે, તેથી જેમણે તૌબા કરી અને તારા માર્ગે ચાલ્યા તેમને માફ કર, અને તેમને જહન્નમના અઝાબથી બચાવ.", "અર્શ ઉપાડનાર ફરિશ્તાઓ મોમિનો માટે આ દુઆ કરે છે.", "ફરિશ્તાઓની દુઆમાં શામેલ થવાની નિય્યતથી."),
        "dua_q_ikhwanina" to DuaText("અમારા પહેલાંના ભાઈઓ માટે", "હે અમારા રબ! અમને અને અમારા તે ભાઈઓને માફ કર જે અમારા પહેલાં ઈમાન લાવ્યા, અને અમારા દિલોમાં ઈમાનવાળાઓ માટે કોઈ કીનો ન રાખ. હે અમારા રબ! નિઃશંક તું ખૂબ મહેરબાન, દયાળુ છે.", "અગાઉના મોમિનો માટે અને દિલની સફાઈની દુઆ.", "સહાબા (ર.) અને અગાઉના મોમિનો માટે દુઆ."),
        "dua_q_alayka_tawakkalna" to DuaText("તારા પર જ અમે ભરોસો કર્યો (ઇબ્રાહીમ અ.)", "હે અમારા રબ! અમે તારા પર ભરોસો કર્યો, તારી તરફ રુજૂ કર્યું અને તારી જ તરફ પાછા ફરવાનું છે. હે અમારા રબ! અમને કાફિરો માટે આઝમાઇશ ન બનાવ અને અમને માફ કર. હે અમારા રબ! નિઃશંક તું જબરદસ્ત, હિકમતવાળો છે.", "ઇબ્રાહીમ (અ.) અને તેમના સાથીઓની દુઆ.", "ભરોસો અને રુજૂની દુઆ."),
        "dua_q_atmim_nurana" to DuaText("અમારો નૂર પૂરો કર", "હે અમારા રબ! અમારા માટે અમારો નૂર પૂરો કર અને અમને માફ કર, નિઃશંક તું દરેક વસ્તુ પર સમર્થ છે.", "કયામતના દિવસે મોમિનોની દુઆ.", "પુલ-સિરાત પર નૂરની માગણી."),
        "dua_q_asiya_baytan" to DuaText("જન્નતમાં ઘર (આસિયા)", "હે મારા રબ! મારા માટે તારી પાસે જન્નતમાં ઘર બનાવ, અને મને ફિરઔન અને તેનાં કર્મોથી છુટકારો આપ, અને જાલિમ કોમથી છુટકારો આપ.", "ફિરઔનની પત્ની આસિયાની દુઆ.", "અલ્લાહે તેમને મોમિનો માટે ઉદાહરણ બનાવ્યાં."),
        "dua_adhan_response" to DuaText("અઝાનનો જવાબ", "અલ્લાહ વિના ન કોઈ શક્તિ છે ન કોઈ સામર્થ્ય.", "મુઅઝ્ઝિન જે કહે તે જ દોહરાવો; 'હય્યા અલસ્સલાહ' અને 'હય્યા અલલ ફલાહ' પર આ કહો.", "દિલથી જવાબ આપનાર જન્નતમાં પ્રવેશશે."),
        "dua_adhan_shahadah" to DuaText("મુઅઝ્ઝિનની શહાદત પછી", "અને હું પણ ગવાહી આપું છું કે અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, અને મુહમ્મદ ﷺ તેના બંદા અને રસૂલ છે. હું અલ્લાહને રબ, મુહમ્મદ ﷺ ને રસૂલ અને ઇસ્લામને દીન તરીકે પામીને રાજી છું.", "મુઅઝ્ઝિનની શહાદતૈન સાંભળીને.", "તેનાં પાપ માફ કરી દેવાય છે."),
        "dua_istiftah_baid" to DuaText("શરૂઆતની દુઆ: મને પાપોથી દૂર કર", "હે અલ્લાહ! મારી અને મારાં પાપો વચ્ચે એટલું અંતર કરી દે જેટલું તેં પૂર્વ અને પશ્ચિમ વચ્ચે કર્યું. હે અલ્લાહ! મને પાપોથી એવો સાફ કર જેમ સફેદ કપડું મેલથી સાફ કરાય છે. હે અલ્લાહ! મારાં પાપ પાણી, બરફ અને કરાથી ધોઈ નાખ.", "તકબીરે તહરીમા પછી (સનાની જગ્યાએ પણ પઢી શકાય).", "નબી ﷺ તકબીર અને કિરાઅત વચ્ચે આ પઢતા."),
        "dua_hamdan_kathiran" to DuaText("રુકૂ પછી ઘણી પ્રશંસા", "હે અમારા રબ! તારા માટે જ પ્રશંસા છે — ઘણી, પવિત્ર અને બરકતવાળી પ્રશંસા.", "રુકૂમાંથી ઊઠીને 'રબ્બના લકલ હમ્દ' સાથે.", "ત્રીસથી વધુ ફરિશ્તાઓ તેને પહેલાં લખવા માટે એકબીજાથી આગળ વધતા હતા."),
        "dua_subbuhun_quddus" to DuaText("સુબ્બૂહુન કુદ્દૂસ (રુકૂ અને સિજદો)", "(અલ્લાહ) અત્યંત પવિત્ર, અત્યંત પાક છે, ફરિશ્તાઓ અને રૂહ (જિબ્રીલ) નો રબ.", "રુકૂ અને સિજદામાં.", "નબી ﷺ રુકૂ અને સિજદામાં આ પઢતા."),
        "dua_sujood_dhanbi_kullah" to DuaText("સિજદામાં: મારાં બધાં પાપ માફ કર", "હે અલ્લાહ! મારાં બધાં પાપ માફ કર — નાનાં અને મોટાં, પહેલાંનાં અને પછીનાં, જાહેર અને છૂપાં.", "સિજદામાં.", "સિજદો દુઆ કબૂલ થવાની જગ્યા છે."),
        "dua_sujood_ridaka" to DuaText("તારી પ્રસન્નતાની પનાહ", "હે અલ્લાહ! હું તારી પ્રસન્નતા દ્વારા તારી નારાજગીથી, તારી માફી દ્વારા તારી સજાથી પનાહ માગું છું, અને તારાથી તારી જ પનાહ માગું છું. હું તારી પ્રશંસાનો હક અદા કરી શકતો નથી, તું તેવો જ છે જેવી તેં પોતાની પ્રશંસા કરી.", "સિજદામાં — આઇશા (ર.) એ નબી ﷺ ને આ પઢતા સાંભળ્યા.", "નબી ﷺ ની સિજદાની દુઆ."),
        "dua_tashahhud" to DuaText("તશહ્હુદ (અત્તહિય્યાત)", "તમામ મૌખિક, શારીરિક અને આર્થિક ઇબાદતો અલ્લાહ માટે છે. હે નબી! આપ પર સલામ, અલ્લાહની રહમત અને તેની બરકતો હો. અમારા પર અને અલ્લાહના નેક બંદાઓ પર સલામ હો. હું ગવાહી આપું છું કે અલ્લાહ સિવા કોઈ પૂજ્ય નથી, અને ગવાહી આપું છું કે મુહમ્મદ ﷺ તેના બંદા અને રસૂલ છે.", "દરેક કઅદામાં — અબ્દુલ્લાહ બિન મસઊદ (ર.) ની રિવાયત (હનફીઓનો અમલ).", "નબી ﷺ તેને કુરઆનની સૂરહની જેમ શીખવતા."),
        "dua_sajdah_tilawah" to DuaText("સજદએ તિલાવત", "મારા ચહેરાએ તેને સિજદો કર્યો જેણે તેને સર્જ્યો અને પોતાની શક્તિ અને સામર્થ્યથી તેના કાન અને આંખો બનાવ્યાં.", "સજદએ તિલાવતમાં.", "નબી ﷺ રાત્રિના સજદએ તિલાવતમાં આ પઢતા."),
        "dua_after_witr" to DuaText("વિત્ર પછી", "પવિત્ર છે બાદશાહ, અત્યંત પાક.", "વિત્રના સલામ પછી ત્રણ વખત, ત્રીજી વખત ઊંચા અવાજે.", "નબી ﷺ વિત્ર પછી આ ફરમાવતા."),
        "dua_tahajjud_nur" to DuaText("તહજ્જુદની શરૂઆતની દુઆ", "હે અલ્લાહ! તારા માટે જ પ્રશંસા છે, તું આકાશો, ધરતી અને તેમાં જે છે તેનો આધાર છે. તારા માટે જ પ્રશંસા છે, તું આકાશો, ધરતી અને તેમાં જે છે તેનો નૂર છે. તારા માટે જ પ્રશંસા છે, તું સત્ય છે, તારું વચન સત્ય છે, તારી મુલાકાત સત્ય છે, તારું કથન સત્ય છે, જન્નત સત્ય છે, જહન્નમ સત્ય છે, નબીઓ સત્ય છે, મુહમ્મદ ﷺ સત્ય છે અને કયામત સત્ય છે.", "રાત્રિની નમાઝ (તહજ્જુદ) શરૂ કરતી વખતે (દુઆનો શરૂઆતનો ભાગ).", "નબી ﷺ તહજ્જુદ માટે ઊઠીને આ પઢતા (સંપૂર્ણ દુઆ બુખારીમાં છે)."),
        "dua_rabba_jibrail" to DuaText("વિવાદિત બાબતોમાં માર્ગદર્શન", "હે અલ્લાહ, જિબ્રીલ, મીકાઈલ અને ઇસ્રાફીલના રબ, આકાશો અને ધરતીના સર્જનહાર, છૂપા અને જાહેરના જાણનાર! તું તારા બંદાઓ વચ્ચે એ બાબતોનો ફેંસલો કરીશ જેમાં તેઓ મતભેદ કરતા. જે સત્યમાં મતભેદ થયો, તારા હુકમથી તેમાં મારું માર્ગદર્શન કર. નિઃશંક તું જેને ચાહે સીધો માર્ગ બતાવે છે.", "તહજ્જુદની શરૂઆતમાં — મતભેદના સમયે સત્યનું માર્ગદર્શન.", "નબી ﷺ રાત્રિની નમાઝ આ જ દુઆથી શરૂ કરતા."),
        "dua_going_to_mosque_nur" to DuaText("મસ્જિદ જતી વખતે (નૂરની દુઆ)", "હે અલ્લાહ! મારા દિલમાં નૂર કરી દે, મારી આંખોમાં નૂર, મારા કાનોમાં નૂર, મારી જમણી બાજુ નૂર, મારી ડાબી બાજુ નૂર, મારી ઉપર નૂર, મારી નીચે નૂર, મારી આગળ નૂર, મારી પાછળ નૂર, અને મારા માટે નૂર બનાવી દે.", "ફજર માટે મસ્જિદ જતી વખતે.", "નબી ﷺ નમાઝ માટે નીકળતી વખતે આ પઢતા."),
        "dua_waswasa_salah" to DuaText("નમાઝમાં વસવસો (ખિંઝબ)", "હું ધિક્કારાયેલા શૈતાનથી અલ્લાહની પનાહ માગું છું.", "નમાઝમાં શૈતાની વસવસા આવે તો પનાહ માગીને ડાબી બાજુ ત્રણ વખત હળવું થૂંકો.", "ઉસ્માન બિન અબિલ આસ (ર.) એ આમ કર્યું અને વસવસો ચાલ્યો ગયો."),
        "dua_alimal_ghayb" to DuaText("ગૈબના જાણનાર", "હે અલ્લાહ, ગૈબ અને હાજરના જાણનાર, આકાશો અને ધરતીના સર્જનહાર, દરેક વસ્તુના રબ અને માલિક! હું ગવાહી આપું છું કે તારા સિવા કોઈ પૂજ્ય નથી. હું મારા મનની બૂરાઈથી, અને શૈતાનની બૂરાઈ અને તેના શિર્કથી તારી પનાહ માગું છું.", "સવાર, સાંજ અને સૂતાં પહેલાં — નબી ﷺ એ અબૂ બક્ર (ર.) ને શીખવી.", "મન અને શૈતાનની બૂરાઈથી રક્ષણ."),
        "dua_fitratil_islam" to DuaText("ઇસ્લામની ફિતરત પર", "અમે ઇસ્લામની ફિતરત પર, કલિમએ ઇખ્લાસ પર, અમારા નબી મુહમ્મદ ﷺ ના દીન પર અને અમારા પિતા ઇબ્રાહીમ (અ.) ની મિલ્લત પર સવાર કરી, જે એકનિષ્ઠ મુસ્લિમ હતા અને મુશરિકોમાંથી ન હતા.", "સવારે.", "દરેક સવારે ઈમાનનું નવીકરણ."),
        "dua_amsayna_fitrah" to DuaText("સાંજે ઇસ્લામની ફિતરત પર", "અમે ઇસ્લામની ફિતરત પર, કલિમએ ઇખ્લાસ પર, અમારા નબી મુહમ્મદ ﷺ ના દીન પર અને અમારા પિતા ઇબ્રાહીમ (અ.) ની મિલ્લત પર સાંજ કરી, જે એકનિષ્ઠ મુસ્લિમ હતા અને મુશરિકોમાંથી ન હતા.", "સાંજે.", "દરેક સાંજે ઈમાનનું નવીકરણ."),
        "dua_tahleel_10_fajr" to DuaText("ફજર અને મગરિબ પછી દસ વખત તહલીલ", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, રાજ્ય અને પ્રશંસા તેની જ છે, તે જ જીવન આપે છે અને મૃત્યુ આપે છે, અને તે દરેક વસ્તુ પર સમર્થ છે.", "ફજર (અને મગરિબ) પછી, પગ વાળ્યા અને વાત કર્યા વિના દસ વખત.", "દસ નેકીઓ, દસ પાપ માફ, દસ દરજ્જા બુલંદ અને આખો દિવસ શૈતાનથી રક્ષણ."),
        "dua_la_hawla_kanz" to DuaText("જન્નતનો ખજાનો", "અલ્લાહ વિના ન કોઈ શક્તિ છે ન કોઈ સામર્થ્ય.", "દરેક સમયે વારંવાર.", "આ જન્નતના ખજાનાઓમાંથી એક ખજાનો છે."),
        "dua_four_beloved_words" to DuaText("સૌથી પ્રિય ચાર વાક્યો", "અલ્લાહ પવિત્ર છે, બધી પ્રશંસા અલ્લાહ માટે છે, અલ્લાહ સિવા કોઈ પૂજ્ય નથી, અને અલ્લાહ સૌથી મહાન છે.", "અલ્લાહને સૌથી પસંદ વાક્યો.", "નબી ﷺ ને આ દરેક એ વસ્તુથી વધુ પ્રિય છે જેના પર સૂરજ ઊગે છે."),
        "dua_two_light_words" to DuaText("જીભ પર હળવાં બે વાક્યો", "અલ્લાહ પવિત્ર છે અને પ્રશંસા તેની જ છે, મહાન અલ્લાહ પવિત્ર છે.", "જીભ પર હળવાં, ત્રાજવામાં ભારે.", "રહમાનને પ્રિય, જીભ પર હળવાં અને ત્રાજવામાં ભારે. (બુખારીની છેલ્લી હદીસ)"),
        "dua_ya_dhal_jalal" to DuaText("યા ઝલ જલાલિ વલ ઇક્રામ", "હે મહિમા અને સન્માનના માલિક!", "દુઆમાં તેને વળગી રહો — નબી ﷺ નો હુકમ.", "નબી ﷺ એ ફરમાવ્યું: 'યા ઝલ જલાલિ વલ ઇક્રામ' ને વળગી રહો."),
        "dua_sleep_wadatu_janbi" to DuaText("તારા નામથી મેં પડખું મૂક્યું", "હે મારા રબ! તારા નામથી મેં મારું પડખું મૂક્યું અને તારા જ નામથી ઊઠીશ. જો તું મારી રૂહ રોકી લે તો તેના પર દયા કર, અને જો છોડી દે તો તેનું એવું રક્ષણ કર જેવું તું તારા નેક બંદાઓનું કરે છે.", "પથારી ઝાટકીને સૂઈ ગયા પછી.", "સૂતાં પહેલાં રૂહને અલ્લાહને સોંપવી."),
        "dua_sleep_khalaqta_nafsi" to DuaText("તેં મારો આત્મા સર્જ્યો", "હે અલ્લાહ! તેં મારો આત્મા સર્જ્યો અને તું જ તેને મૃત્યુ આપીશ. તેનું મરવું અને જીવવું તારા માટે જ છે. જો તું તેને જીવિત રાખે તો તેનું રક્ષણ કર, અને જો મૃત્યુ આપે તો તેને માફ કર. હે અલ્લાહ! હું તારી પાસે સલામતી માગું છું.", "સૂતાં પહેલાં — ઇબ્ને ઉમર (ર.) ની રિવાયત.", "નબી ﷺ એ સૂતી વખતે આ પઢવાનો હુકમ આપ્યો."),
        "dua_sleep_atamana" to DuaText("સૂતાં પહેલાં આભાર", "બધી પ્રશંસા અલ્લાહ માટે જેણે અમને ખવડાવ્યું, પીવડાવ્યું, અમારી જરૂરિયાત પૂરી કરી અને અમને ઠેકાણું આપ્યું. કેટલા લોકો છે જેમની જરૂરિયાત પૂરી કરનાર કોઈ નથી ન ઠેકાણું આપનાર.", "પથારીમાં જતી વખતે.", "નબી ﷺ પથારીમાં જતી વખતે આ ફરમાવતા."),
        "dua_sleep_rabbas_samawat" to DuaText("આકાશોના રબ — અમારું દેવું ચૂકવી દે", "હે અલ્લાહ, આકાશો, ધરતી અને મહાન અર્શના રબ, અમારા અને દરેક વસ્તુના રબ, દાણા અને ગોટલીને ફાડનાર, તૌરાત, ઇન્જીલ અને ફુરકાન ઉતારનાર! હું દરેક એ વસ્તુની બૂરાઈથી તારી પનાહ માગું છું જેનું કપાળ તારા કબજામાં છે. હે અલ્લાહ! તું જ પ્રથમ છે, તારા પહેલાં કંઈ નથી; તું જ અંતિમ છે, તારા પછી કંઈ નથી; તું જ પ્રગટ છે, તારી ઉપર કંઈ નથી; તું જ ગુપ્ત છે, તારાથી છૂપું કંઈ નથી. અમારું દેવું ચૂકવી દે અને અમને ગરીબીથી મુક્ત કર.", "સૂતાં પહેલાં જમણા પડખે — ફાતિમા (ર.) ને શીખવી.", "દેવું અને તંગીથી છુટકારાની દુઆ."),
        "dua_sleep_fear" to DuaText("ઊંઘમાં ડર કે ગભરાટ", "હું અલ્લાહના સંપૂર્ણ કલિમાતની પનાહ માગું છું તેના ગુસ્સા અને સજાથી, તેના બંદાઓની બૂરાઈથી, અને શૈતાનોના વસવસાથી અને તેઓ મારી પાસે આવે તેનાથી.", "ઊંઘમાં ગભરાટ કે ડર લાગે ત્યારે.", "આમ કરવાથી તે વસ્તુ નુકસાન નહીં કરે."),
        "dua_waking_afani" to DuaText("જાગતાં: તેણે મારી રૂહ પાછી આપી", "બધી પ્રશંસા અલ્લાહ માટે જેણે મારા શરીરને સલામતી આપી, મારી રૂહ મને પાછી આપી અને મને તેના ઝિક્રની પરવાનગી આપી.", "જાગતી વખતે.", "નવી સવાર માટે આભાર."),
        "dua_allahu_rabbi" to DuaText("અલ્લાહ, અલ્લાહ મારો રબ છે", "અલ્લાહ, અલ્લાહ મારો રબ છે, હું તેની સાથે કોઈ વસ્તુને ભાગીદાર ઠેરવતો નથી.", "દુઃખ કે ચિંતાના સમયે — નબી ﷺ એ અસ્મા બિન્તે ઉમૈસ (ર.) ને શીખવી.", "ચિંતાના સમયે તૌહીદનો સહારો."),
    )
}
